-- ============================================================================
-- jagger_menu.sql — peuplement du menu Jagger.
-- 22 catégories, 121 plats, 121 prix (menu_item_sizes, size_label = 'Standard').
-- N'altère aucune table, fonction, trigger, RLS, index ni policy : uniquement
-- des INSERT/UPDATE de données sur le schéma existant. Ré-exécutable.
-- ============================================================================

BEGIN;

-- ─── 1. Catégories (créées seulement si absentes) ───────────────────────────
WITH data(name, display_order) AS (
  VALUES
    ('Cafés', 1),
    ('Signatures', 2),
    ('Thés', 3),
    ('Jus frais', 4),
    ('Cocktails', 5),
    ('Mojitos', 6),
    ('Milkshakes', 7),
    ('Frappuccinos', 8),
    ('Chocolats', 9),
    ('Smoothie bowls', 10),
    ('Desserts', 11),
    ('Crêpes sucrées', 12),
    ('Crêpes salées', 13),
    ('Gaufres sucrées', 14),
    ('Gaufres salées', 15),
    ('Pancakes', 16),
    ('Sandwichs', 17),
    ('Salades', 18),
    ('Pasta', 19),
    ('Plats', 20),
    ('Chichas', 21),
    ('Boissons', 22)
)
INSERT INTO public.categories (name, display_order)
SELECT d.name, d.display_order
FROM data d
WHERE NOT EXISTS (
  SELECT 1 FROM public.categories c WHERE lower(btrim(c.name)) = lower(btrim(d.name))
);

-- Ordre d'affichage des catégories aligné sur la carte.
WITH data(name, display_order) AS (
  VALUES
    ('Cafés', 1),
    ('Signatures', 2),
    ('Thés', 3),
    ('Jus frais', 4),
    ('Cocktails', 5),
    ('Mojitos', 6),
    ('Milkshakes', 7),
    ('Frappuccinos', 8),
    ('Chocolats', 9),
    ('Smoothie bowls', 10),
    ('Desserts', 11),
    ('Crêpes sucrées', 12),
    ('Crêpes salées', 13),
    ('Gaufres sucrées', 14),
    ('Gaufres salées', 15),
    ('Pancakes', 16),
    ('Sandwichs', 17),
    ('Salades', 18),
    ('Pasta', 19),
    ('Plats', 20),
    ('Chichas', 21),
    ('Boissons', 22)
)
UPDATE public.categories c
SET display_order = d.display_order
FROM data d
WHERE lower(btrim(c.name)) = lower(btrim(d.name))
  AND c.display_order IS DISTINCT FROM d.display_order;

