INSERT INTO public.menu_items (category_id, name, description, image_url, is_available, display_order)
SELECT c.id, d.dish, d.descr, d.img, true, d.display_order
FROM data d
JOIN public.categories c ON lower(btrim(c.name)) = lower(btrim(d.cat))
WHERE NOT EXISTS (
  SELECT 1 FROM public.menu_items mi
  WHERE mi.category_id = c.id AND lower(btrim(mi.name)) = lower(btrim(d.dish))
);

