UPDATE public.menu_items mi
SET description   = d.descr,
    image_url     = d.img,
    display_order = d.display_order,
    is_available  = true,
    updated_at    = now()
FROM data d
JOIN public.categories c ON lower(btrim(c.name)) = lower(btrim(d.cat))
WHERE mi.category_id = c.id
  AND lower(btrim(mi.name)) = lower(btrim(d.dish));

