INSERT INTO public.menu_item_sizes (menu_item_id, size_label, price, display_order)
SELECT mi.id, 'Standard', d.price, 1
FROM data d
JOIN public.categories c ON lower(btrim(c.name)) = lower(btrim(d.cat))
JOIN public.menu_items mi ON mi.category_id = c.id
  AND lower(btrim(mi.name)) = lower(btrim(d.dish))
WHERE NOT EXISTS (
  SELECT 1 FROM public.menu_item_sizes s
  WHERE s.menu_item_id = mi.id AND s.size_label = 'Standard'
);

