UPDATE public.menu_item_sizes s
SET price = d.price
FROM data d
JOIN public.categories c ON lower(btrim(c.name)) = lower(btrim(d.cat))
JOIN public.menu_items mi ON mi.category_id = c.id
  AND lower(btrim(mi.name)) = lower(btrim(d.dish))
WHERE s.menu_item_id = mi.id
  AND s.size_label = 'Standard'
  AND s.price IS DISTINCT FROM d.price;

COMMIT;

-- ─── Contrôle ───────────────────────────────────────────────────────────────
-- Attendu : 22 catégories, 121 plats, 121 prix, 0 plat sans prix,
--           117 plats avec image.
SELECT (SELECT count(*) FROM public.categories)                          AS categories,
       (SELECT count(*) FROM public.menu_items)                          AS plats,
       (SELECT count(*) FROM public.menu_item_sizes)                     AS prix,
       (SELECT count(*) FROM public.menu_items mi WHERE NOT EXISTS (
          SELECT 1 FROM public.menu_item_sizes s WHERE s.menu_item_id = mi.id)) AS plats_sans_prix,
       (SELECT count(*) FROM public.menu_items WHERE image_url IS NOT NULL)     AS plats_avec_image;
